import re

def mask_card_number(text: str) -> str | None:
    text = text.strip()
    cleaned = re.sub(r'[ -]', '', text)

    if not re.fullmatch(r'\d{13,19}', cleaned):
        return None

    if not luhn_checksum(cleaned):
        return None

    masked = '*' * (len(cleaned) - 4) + cleaned[-4:]
    return ' '.join(masked[i:i+4] for i in range(0, len(masked), 4))

def luhn_checksum(card_number: str) -> bool:
    total = 0
    num_digits = len(card_number)
    parity = num_digits % 2

    for i, digit in enumerate(card_number):
        n = int(digit)
        if i % 2 == parity:
            n *= 2
            if n > 9:
                n -= 9
        total += n

    return total % 10 == 0
